<?php
function nexa_ssl_apply(): void { if(headers_sent()) return; header('X-Content-Type-Options: nosniff'); header('X-Frame-Options: SAMEORIGIN'); header('Referrer-Policy: strict-origin-when-cross-origin'); if((string)get_setting('ssl_force','0')!=='1') return; $proto=strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO']??($_SERVER['HTTPS']??''))); $isHttps=($proto==='https'||$proto==='on'||$proto==='1'); $host=(string)($_SERVER['HTTP_HOST']??''); if(!$isHttps && $host!=='' && !preg_match('/^(localhost|127\.0\.0\.1)/',$host) && (($_SERVER['REQUEST_METHOD']??'GET')==='GET')){ header('Location: https://'.$host.($_SERVER['REQUEST_URI']??'/'),true,301); exit; } }
